traits <- traits[, apply(traits, 2, var) > 0]
ppca <- phyl.pca(pruned_tree, traits, method = "BM", mode = "corr")
write.csv(ppca$L, "ppca_loadings_seed1.csv")
write.csv(ppca$S, "ppca_scores_seed1.csv")
eig_df <- data.frame(
    PC = rownames(ppca$Eval),
    eigenvalue = diag(ppca$Eval),
    variance_explained = diag(ppca$Eval) / sum(diag(ppca$Eval)) * 100)
write.csv(eig_df, "ppca_eigenvalues_seed1.csv", row.names = FALSE)
pdf("ppca_biplot_seed1.pdf", width=14, height=14)
biplot(ppca,
       cex = c(0.0001, 0.8),
       col = c("grey70", "red"),
       arrow.len = 0.05)
dev.off()
cat("pPCA seed 1 complete\n")
